import json, sys, urllib.request

BASE = "https://api.plateauview.mlit.go.jp/mcp"
HDRS = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream"}

def post(payload):
    req = urllib.request.Request(BASE, data=json.dumps(payload).encode("utf-8"), headers=HDRS, method="POST")
    with urllib.request.urlopen(req, timeout=120) as res:
        ct = res.headers.get("Content-Type", "")
        raw = res.read().decode("utf-8")
    if "event-stream" in ct:
        # parse SSE: lines "event: message" / "data: {...}"
        out = []
        for line in raw.splitlines():
            if line.startswith("data:"):
                out.append(line[5:].strip())
        return "\n".join(out)
    return raw

init = {"jsonrpc":"2.0","id":1,"method":"initialize","params":{"protocolVersion":"2024-11-05","capabilities":{},"clientInfo":{"name":"kph2026","version":"0.0.1"}}}
print("initialize:", post(init)[:300])

notify = {"jsonrpc":"2.0","method":"notifications/initialized"}
try:
    post(notify)
    print("initialized notify sent")
except Exception as e:
    print("notify err", e)

tools = {"jsonrpc":"2.0","id":2,"method":"tools/list","params":{}}
