import os, re, shutil, sys, json

SRC = r"C:\Users\81704\Downloads\1010　Hackathon\ecc\skills"
DST = r"C:\Users\81704\Downloads\1010　Hackathon\.opencode\skill"

PICK = [
    "coding-standards", "frontend-patterns", "vite-patterns", "error-handling",
    "tdd-workflow", "verification-loop", "git-workflow", "security-review",
    "search-first", "deep-research", "documentation-lookup", "ui-demo",
    "browser-qa", "frontend-a11y", "context-budget", "python-patterns", "python-testing",
]

FM_RE = re.compile(r"^---\s*\n(.*?)\n---\s*\n", re.S)

def scalar(v):
    v = v.strip()
    if v.startswith("[") and v.endswith("]"):
        v = v[1:-1].strip()
    if v.startswith('"') and v.endswith('"'):
        v = v[1:-1]
    if v.startswith("'") and v.endswith("'"):
        v = v[1:-1]
    return v

def parse_kv(text):
    """very small subset YAML parser for flat / folded scalars"""
    out = {}
    lines = text.split("\n")
    i = 0
    while i < len(lines):
        line = lines[i]
        if not line.strip() or line.lstrip().startswith("#"):
            i += 1
            continue
        m = re.match(r"^([A-Za-z0-9_\-]+):(?:\s+(.*))?$", line)
        if not m:
            i += 1
            continue
        key, val = m.group(1), (m.group(2) or "").strip()
        if val in (">-", ">", "|-", "|"):
            # folded block: consume following indented lines
            buf = []
            i += 1
            while i < len(lines) and (lines[i].startswith((" ", "\t")) or not lines[i].strip()):
                if lines[i].strip():
                    buf.append(lines[i].strip())
                i += 1
            joined = " ".join(buf)
            if val.startswith(">"):
                val = joined
        elif val.startswith("[") and not val.endswith("]"):
            # inline list spanning lines until ]
            buf = [val[1:].strip()]
            i += 1
            while i < len(lines) and not lines[i].strip().endswith("]"):
                buf.append(lines[i].strip(" ,"))
                i += 1
            if i < len(lines):
                buf.append(lines[i].strip().rstrip("]").strip())
            val = ",".join([b for b in buf if b])
        out[key] = val
        i += 1
    return out

def normalize(name, path):
    raw = open(path, encoding="utf-8").read()
    m = FM_RE.match(raw)
    if not m:
        return None, "no frontmatter"
    kv = parse_kv(m.group(1))
    body = raw[m.end():]
    desc = kv.get("description", "")
    desc = scalar(desc)
    if not desc:
        return None, "missing description"
    # description may be folded; keep as-is string
    desc = desc.replace("\n", " ")
    meta = {}
    for k, v in kv.items():
        if k in ("name", "description", "license"):
            continue
        meta[k] = scalar(v).replace("\n", " ")[:300]
    fm = ["---", f"name: {name}", f"description: {desc}"]
    if kv.get("license"):
        fm.append(f"license: {scalar(kv['license'])}")
    if meta:
        fm.append("metadata:")
        for k, v in sorted(meta.items()):
            v = v.replace('"', "'")
            fm.append(f'  {k}: "{v}"')
    fm.append("---")
    return "\n".join(fm) + "\n\n" + body.lstrip("\n"), None

def main():
    os.makedirs(DST, exist_ok=True)
    ok, skipped = [], []
    for name in PICK:
        s = os.path.join(SRC, name)
        d = os.path.join(DST, name)
        if not os.path.isdir(s):
            skipped.append((name, "source missing"))
            continue
        skill_md = os.path.join(s, "SKILL.md")
        if not os.path.isfile(skill_md):
            skipped.append((name, "no SKILL.md"))
            continue
        new_md, err = normalize(name, skill_md)
        if err:
            skipped.append((name, err))
            continue
        if os.path.isdir(d):
            shutil.rmtree(d)
        os.makedirs(d)
        with open(os.path.join(d, "SKILL.md"), "w", encoding="utf-8") as f:
            f.write(new_md)
        # copy supporting files (references/, scripts/, examples/, assets/)
        for entry in os.listdir(s):
            sp = os.path.join(s, entry)
            if entry == "SKILL.md" or not os.path.isfile(sp):
                shutil.copytree(sp, os.path.join(d, entry), dirs_exist_ok=True)
            else:
                shutil.copy2(sp, os.path.join(d, entry))
        ok.append(name)
    print("installed:", len(ok))
    for o in ok:
        print("  -", o)
    if skipped:
        print("skipped:", skipped)

main()

