import os, re, sys, io
sys.stdout = io.TextIOWrapper(sys.stdout.buffer, encoding="utf-8", errors="replace")
DST = r"C:\Users\81704\Downloads\1010　Hackathon\.opencode\skill"
try:
    import yaml
    have_yaml = True
except Exception:
    have_yaml = False
print("has pyyaml:", have_yaml)

for name in sorted(os.listdir(DST)):
    p = os.path.join(DST, name, "SKILL.md")
    if not os.path.isfile(p):
        print("!! no SKILL.md:", name); continue
    raw = open(p, encoding="utf-8").read()
    m = re.match(r"^---\s*\n(.*?)\n---\s*\n", raw, re.S)
    if not m:
        print("!! no frontmatter:", name); continue
    fm = m.group(1)
    if have_yaml:
        try:
            d = yaml.safe_load(fm)
            if not isinstance(d, dict):
                print("!! fm not dict:", name, type(d)); continue
            keys = list(d.keys())
            desc = str(d.get("description", ""))
            missing = [k for k in ("name", "description") if not d.get(k)]
            print(f"OK {name:22s} desc_len={len(desc):4d} keys={keys}" + (" MISSING=" + str(missing) if missing else ""))
        except Exception as e:
            print("!! yaml error:", name, e)
    else:
        print(f"?  {name:22s} len={len(fm)}")
    if len(raw) > 200000:
        print("   note: large body", name, len(raw))

import json, urllib.request

BASE = "https://api.plateauview.mlit.go.jp/mcp"
HDRS = {"Content-Type": "application/json", "Accept": "application/json, text/event-stream"}

def rpc(method, params=None, rid=1):
    payload = {"jsonrpc": "2.0", "id": rid, "method": method}
    if params is not None:
        payload["params"] = params
    req = urllib.request.Request(BASE, data=json.dumps(payload, ensure_ascii=False).encode("utf-8"), headers=HDRS, method="POST")
    with urllib.request.urlopen(req, timeout=180) as res:
        ct = res.headers.get("Content-Type", "")
        raw = res.read().decode("utf-8")
    if "event-stream" in ct:
        for line in raw.splitlines():
            if line.startswith("data:"):
                return json.loads(line[5:].strip())
        raise RuntimeError("no data in SSE: " + raw[:300])
    return json.loads(raw)

def call_tool(name, args, rid=10):
    r = rpc("tools/call", {"name": name, "arguments": args}, rid)
    if "error" in r:
        return {"_error": r["error"]}
    content = r.get("result", {}).get("content", [])
    texts = [c.get("text", "") for c in content if c.get("type") == "text"]
    return {"_texts": texts, "_raw": r}

# 0. schemas on file
tools = json.load(open("mcp_tools.json", encoding="utf-8"))
for t in tools:
    if t["name"] in ("plateau_search_areas", "plateau_search_datasets", "plateau_get_citygml_files"):
        print("SCHEMA", t["name"], json.dumps(t.get("inputSchema", {}), ensure_ascii=False)[:600])

# 1. initialize handshake
print("INIT:", json.dumps(rpc("initialize", {"protocolVersion": "2024-11-05", "capabilities": {}, "clientInfo": {"name": "kph2026", "version": "0.0.1"}}, 1))[:200])
try:
    rpc("notifications/initialized", None, 0)
except Exception:
    pass

