import { defineConfig } from "vite";
import cesium from "vite-plugin-cesium";

export default defineConfig({
  plugins: [cesium()],
  server: { port: 5173 },
});

html, body, #cesium {
  margin: 0;
  padding: 0;
  width: 100%;
  height: 100%;
