import * as Cesium from "cesium";
import "cesium/Build/Cesium/Widgets/widgets.css";
import "./style.css";

/* ============================================================
 * 天空流しそうめんスライダー (kph2026-07)
 * - 背景: PLATEAU 3D都市モデル (Cesium ion Japan 3D Buildings)
 * - スライダー: 七条通上空を東へ下る PolylineVolume チューブ
 * - そうめん装置: チーム製 nagashi-somen.glb を3か所に配置
 * - 火災デモ: 木造密集イメージの火災楕円 + スライダーから放水
 * ========================================================== */

// ---- 0. Cesium ion トークン ----
// https://ion.cesium.com/ で無料登録→ Access Tokens をここに貼る。
// 空のままだと OSM 背景 + 建物なしのフォールバックで動く。
const ION_TOKEN = "";
const JAPAN_BUILDINGS_ASSET = 2602291;

const tokenStatus = document.querySelector("#token-status");
function setStatus(msg: string) {
  if (tokenStatus) tokenStatus.textContent = msg;
}

// ---- 1. Viewer ----
let viewer: Cesium.Viewer;
if (ION_TOKEN) {
  Cesium.Ion.defaultAccessToken = ION_TOKEN;
  viewer = new Cesium.Viewer("cesium", {
    terrain: Cesium.Terrain.fromWorldTerrain(),
    baseLayerPicker: false,
    geocoder: false,
    timeline: false,
    animation: false,
  });
  setStatus("base: ion imagery + terrain");
} else {
  viewer = new Cesium.Viewer("cesium", {
    imageryProvider: new Cesium.UrlTemplateImageryProvider({
      url: "https://tile.openstreetmap.org/{z}/{x}/{y}.png",
      maximumLevel: 19,
      credit: "© OpenStreetMap contributors",
    }),
    baseLayerPicker: false,
    geocoder: false,
    timeline: false,
    animation: false,
  });
  setStatus("base: OSM（ion未設定のため建物は簡易表示）");
}
viewer.scene.globe.depthTestAgainstTerrain = true;

// ---- 2. 京都の3D建物 ----
if (ION_TOKEN) {
  Cesium.Cesium3DTileset.fromIonAssetId(JAPAN_BUILDINGS_ASSET)
    .then((tileset) => {
      viewer.scene.primitives.add(tileset);
      setStatus("base: ion + Japan 3D Buildings 表示中");
    })
    .catch((e) => {
      console.warn("buildings failed", e);
      setStatus("base: ion（建物取得に失敗）");
    });
}

// ---- 3. カメラ初期位置: 京都駅 ----
const STATION = { lon: 135.7585, lat: 34.9875 };
function flyToStation() {
  viewer.camera.flyTo({
    destination: Cesium.Cartesian3.fromDegrees(STATION.lon, STATION.lat, 1400),
    orientation: {
      heading: Cesium.Math.toRadians(0),
      pitch: Cesium.Math.toRadians(-55),
      roll: 0,
    },
    duration: 1.6,
  });
}
flyToStation();

// ---- 4. スライダールート (七条通上空: 京都駅→鴨川) ----
// [lon, lat, height(m)]: 建物高さを避けて150mから45mへ下る
const ROUTE: Array<[number, number, number]> = [
  [135.758, 34.987, 150],
  [135.762, 34.986, 120],
  [135.766, 34.985, 95],
  [135.77, 34.984, 70],
  [135.773, 34.9835, 45],
];
const routeCart = ROUTE.map(([lo, la, h]) =>
  Cesium.Cartesian3.fromDegrees(lo, la, h),
);

// 断面: 半径rの円
function circleShape(radius: number, segments = 14): Cesium.Cartesian2[] {
  const pts: Cesium.Cartesian2[] = [];
  for (let i = 0; i < segments; i++) {
    const a = (2 * Math.PI * i) / segments;
    pts.push(new Cesium.Cartesian2(radius * Math.cos(a), radius * Math.sin(a)));
  }
  return pts;
}

const sliderTube = viewer.entities.add({
  name: "slider-tube",
  polylineVolume: {
    positions: routeCart,
    shape: circleShape(6.0),
    cornerType: Cesium.CornerType.ROUNDED,
    material: Cesium.Color.SKYBLUE.withAlpha(0.75),
  },
});
viewer.entities.add({
  name: "slider-water",
  polylineVolume: {
    positions: routeCart.map((p) =>
      Cesium.Cartesian3.fromDegrees(
        ROUTE[routeCart.indexOf(p)][0],
        ROUTE[routeCart.indexOf(p)][1],
        ROUTE[routeCart.indexOf(p)][2] - 2.2,
      ),
    ),
    shape: circleShape(3.2),
    cornerType: Cesium.CornerType.ROUNDED,
    material: Cesium.Color.DEEPSKYBLUE.withAlpha(0.9),
  },
});

// 支柱 x4
for (const i of [1, 2, 3, 4]) {
  const [lo, la, h] = ROUTE[i];
  viewer.entities.add({
    cylinder: {
      length: h,
      topRadius: 2.2,
      bottomRadius: 3.0,
      material: Cesium.Color.SLATEGRAY.withAlpha(0.9),
    },
    position: Cesium.Cartesian3.fromDegrees(lo, la, h / 2),
  });
}

viewer.entities.add({
  position: Cesium.Cartesian3.fromDegrees(ROUTE[0][0], ROUTE[0][1], ROUTE[0][2] + 12),
  label: {
    text: "START 京都駅上空 150m",
    font: "bold 15px sans-serif",
    fillColor: Cesium.Color.WHITE,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2,
    style: Cesium.LabelStyle.FILL_AND_OUTLINE,
  },
});
viewer.entities.add({
  position: Cesium.Cartesian3.fromDegrees(ROUTE[4][0], ROUTE[4][1], ROUTE[4][2] + 12),
  label: {
    text: "GOAL 鴨川プラザ（避難広場となり）",
    font: "bold 15px sans-serif",
    fillColor: Cesium.Color.WHITE,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2,
    style: Cesium.LabelStyle.FILL_AND_OUTLINE,
  },
});

// ---- 5. そうめん流し: チューブ内を流れる白い束 ----
const SAMPLES = 600;
const samples: Cesium.Cartesian3[] = [];
const sampleLonLat: Array<[number, number]> = [];
{
  // ウェイポイント間を線形補間して密サンプル化
  const segLens: number[] = [];
  let total = 0;
  for (let i = 0; i < routeCart.length - 1; i++) {
    const d = Cesium.Cartesian3.distance(routeCart[i], routeCart[i + 1]);
    segLens.push(d);
    total += d;
  }
  for (let s = 0; s < SAMPLES; s++) {
    const target = (total * s) / (SAMPLES - 1);
    let acc = 0;
    for (let i = 0; i < segLens.length; i++) {
      if (target <= acc + segLens[i] || i === segLens.length - 1) {
        const f = segLens[i] === 0 ? 0 : (target - acc) / segLens[i];
        const p = new Cesium.Cartesian3();
        Cesium.Cartesian3.lerp(routeCart[i], routeCart[i + 1], f, p);
        samples.push(p);
        const [lo0, la0] = ROUTE[i];
        const [lo1, la1] = ROUTE[i + 1];
        sampleLonLat.push([lo0 + (lo1 - lo0) * f, la0 + (la1 - la0) * f]);
        break;
      }
      acc += segLens[i];
    }
  }
}
function sampleAt(t: number): { pos: Cesium.Cartesian3; lon: number; lat: number } {
  const tt = ((t % 1) + 1) % 1;
  const idx = Math.min(Math.floor(tt * SAMPLES), SAMPLES - 1);
  return { pos: samples[idx], lon: sampleLonLat[idx][0], lat: sampleLonLat[idx][1] };
}
function sampleAhead(t: number, dt = 0.012) {
  return sampleAt(t + dt);
}

const PELLETS = 10;
for (let k = 0; k < PELLETS; k++) {
  const phase = k / PELLETS;
  viewer.entities.add({
    position: new Cesium.CallbackProperty(() => sampleAt(simT + phase).pos, false),
    box: {
      dimensions: new Cesium.Cartesian3(0.7, 0.7, 2.4),
      material: Cesium.Color.WHITE,
    },
  });
}

// ---- 6. そうめん装置モデル (チーム製 glb) ----
const SOMEN_SPOTS: Array<{ lon: number; lat: number; heading: number; label: string }> = [
  { lon: 135.7681, lat: 35.0116, heading: 90, label: "鴨川デルタ会場" },
  { lon: 135.7735, lat: 34.983, heading: 45, label: "GOALプラザ会場" },
  { lon: 135.7575, lat: 34.9865, heading: 180, label: "京都駅前会場" },
];
for (const s of SOMEN_SPOTS) {
  const pos = Cesium.Cartesian3.fromDegrees(s.lon, s.lat, 0);
  viewer.entities.add({
    position: pos,
    orientation: Cesium.Transforms.headingPitchRollQuaternion(
      pos,
      new Cesium.HeadingPitchRoll(Cesium.Math.toRadians(s.heading), 0, 0),
    ),
    model: { uri: "/nagashi-somen.glb", scale: 1.0, minimumPixelSize: 24 },
  });
  viewer.entities.add({
    position: Cesium.Cartesian3.fromDegrees(s.lon, s.lat, 8),
    label: {
      text: `🎋 ${s.label}`,
      font: "13px sans-serif",
      fillColor: Cesium.Color.WHITE,
      outlineColor: Cesium.Color.BLACK,
      outlineWidth: 2,
      style: Cesium.LabelStyle.FILL_AND_OUTLINE,
    },
  });
}

// ---- 7. 火災デモ (木造密集イメージ) + 放水 ----
// デモ用火点3つ: ルート北側の町家密集想定エリア
const FIRES: Array<{ lon: number; lat: number; r: number }> = [
  { lon: 135.7665, lat: 34.9895, r: 55 },
  { lon: 135.7695, lat: 34.9905, r: 40 },
  { lon: 135.7645, lat: 34.9915, r: 30 },
];
let waterStartMs: number | null = null;
const fireEntities: Cesium.Entity[] = [];
for (const f of FIRES) {
  const ent = viewer.entities.add({
    position: Cesium.Cartesian3.fromDegrees(f.lon, f.lat, 2),
    ellipse: {
      semiMajorAxis: f.r,
      semiMinorAxis: f.r * 0.8,
      height: 2,
      material: new Cesium.ColorMaterialProperty(
        new Cesium.CallbackProperty((time?: Cesium.JulianDate) => {
          const now = time ? Cesium.JulianDate.toDate(time).getTime() : performance.now();
          let alpha = 0.55 + 0.2 * Math.sin(now / 280);
          if (waterStartMs !== null) {
            const el = (now - waterStartMs) / 1000;
            alpha *= Math.max(0.08, 1 - el / 9);
          }
          return Cesium.Color.RED.withAlpha(Math.max(0.05, Math.min(0.8, alpha)));
        }, false),
      ),
    },
    show: false,
  });
  fireEntities.push(ent);
}
viewer.entities.add({
  position: Cesium.Cartesian3.fromDegrees(135.768, 34.9935, 30),
  label: {
    text: "🔥 木造密集・延焼リスク高（試算デモ）",
    font: "bold 14px sans-serif",
    fillColor: Cesium.Color.YELLOW,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2,
    style: Cesium.LabelStyle.FILL_AND_OUTLINE,
    show: false,
  },
  show: false,
});

// 放水ライン: スライダー中間点から火点へ
const waterLine = viewer.entities.add({
  polyline: {
    positions: [
      Cesium.Cartesian3.fromDegrees(ROUTE[2][0], ROUTE[2][1], ROUTE[2][2]),
      Cesium.Cartesian3.fromDegrees(135.768, 34.9905, 0),
    ],
    width: 9,
    material: Cesium.Color.DEEPSKYBLUE.withAlpha(0.85),
  },
  show: false,
});

// ---- 8. 避難広場 (GOAL横・想定) ----
viewer.entities.add({
  polygon: {
    hierarchy: Cesium.Cartesian3.fromDegreesArray([
      135.7735, 34.982, 135.7755, 34.982, 135.7755, 34.984, 135.7735, 34.984,
    ]),
    height: 1,
    material: Cesium.Color.LIMEGREEN.withAlpha(0.5),
  },
});
viewer.entities.add({
  position: Cesium.Cartesian3.fromDegrees(135.7745, 34.983, 15),
  label: {
    text: "🟩 避難広場（想定・防火用水槽あり）",
    font: "13px sans-serif",
    fillColor: Cesium.Color.WHITE,
    outlineColor: Cesium.Color.BLACK,
    outlineWidth: 2,
    style: Cesium.LabelStyle.FILL_AND_OUTLINE,
  },
});

// ---- 9. ライドモード ----
let simT = 0;
let riding = false;
let lastMs = performance.now();
viewer.clock.onTick.addEventListener(() => {
  const now = performance.now();
  const dt = Math.min((now - lastMs) / 1000, 0.1);
  lastMs = now;
  simT += (dt * 26) / 1450; // 約26m/s、1周56秒
  if (riding) {
    const cur = sampleAt(simT);
    const ahead = sampleAhead(simT);
    const up = new Cesium.Cartesian3();
    Cesium.Cartesian3.normalize(cur.pos, up);
    const behind = sampleAt(simT - 0.018).pos;
    const dest = new Cesium.Cartesian3();
    Cesium.Cartesian3.multiplyByScalar(up, 9, dest);
    Cesium.Cartesian3.add(behind, dest, dest);
    const dLon = ahead.lon - cur.lon;
    const dLat = ahead.lat - cur.lat;
    const heading = Math.atan2(
      dLon * Math.cos(Cesium.Math.toRadians(cur.lat)),
      dLat,
    );
    viewer.camera.setView({
      destination: dest,
      orientation: { heading, pitch: Cesium.Math.toRadians(-18), roll: 0 },
    });
  }
});

// ---- 10. スコア表示 (デモ用試算) ----
document.querySelector("#v-density")!.textContent = "68%（下京メッシュ試算）";
document.querySelector("#v-risk")!.textContent = "0.42（木造率×築年係数）";
document.querySelector("#v-shelter")!.textContent = "GOAL東 120m（想定）";

// ---- 11. ボタン ----
function toggleActive(id: string, on: boolean) {
  document.querySelector(id)?.classList.toggle("active", on);
}
document.querySelector("#btn-station")?.addEventListener("click", () => {
  riding = false;
  toggleActive("#btn-ride", false);
  flyToStation();
});
document.querySelector("#btn-ride")?.addEventListener("click", () => {
  riding = !riding;
  toggleActive("#btn-ride", riding);
});
let fireOn = false;
document.querySelector("#btn-fire")?.addEventListener("click", () => {
  fireOn = !fireOn;
  for (const e of fireEntities) e.show = fireOn;
  toggleActive("#btn-fire", fireOn);
  if (fireOn) {
    viewer.camera.flyTo({
      destination: Cesium.Cartesian3.fromDegrees(135.7675, 34.99, 700),
      orientation: { heading: 0, pitch: Cesium.Math.toRadians(-50), roll: 0 },
      duration: 1.4,
    });
  }
});
document.querySelector("#btn-water")?.addEventListener("click", () => {
  waterLine.show = true;
  waterStartMs = Date.now();
  toggleActive("#btn-water", true);
  window.setTimeout(() => toggleActive("#btn-water", false), 9500);
});
document.querySelector("#btn-reset")?.addEventListener("click", () => {
  riding = false;
  toggleActive("#btn-ride", false);
  fireOn = false;
  for (const e of fireEntities) e.show = false;
  toggleActive("#btn-fire", false);
  waterLine.show = false;
  waterStartMs = null;
  flyToStation();
});

