import json, urllib.request, urllib.parse, time, os

BASE = "https://api.openpoiapi.com/v1/search"
VENUES = {
    "station": (135.7575, 34.9865),
    "goal": (135.7735, 34.9830),
    "delta": (135.7681, 35.0116),
}
QUERIES = [("コンビニ", 10), ("駅", 5), ("カフェ", 8), ("飲食店", 8)]

def search(q, lon, lat, radius, limit):
    params = {"q": q, "center": f"{lon},{lat}", "radius": radius, "limit": limit}
    url = BASE + "?" + urllib.parse.urlencode(params)
    req = urllib.request.Request(url, headers={"User-Agent": "kph2026-07"})
    with urllib.request.urlopen(req, timeout=30) as res:
        return json.loads(res.read().decode("utf-8"))

out, seen = [], set()
for vname, (lon, lat) in VENUES.items():
    for q, lim in QUERIES:
        try:
            d = search(q, lon, lat, 600, lim)
        except Exception as e:
            print("ERR", vname, q, e)
            continue
        for r in d.get("results", []):
            key = (r.get("name"), round(float(r.get("lat", 0)), 5), round(float(r.get("lng", 0)), 5))
            if key in seen:
                continue
            seen.add(key)
            out.append({
