"""CityGML bldg parser -> stats.json + wooden.json (streaming, namespace-agnostic)."""
import json, os, sys, math
from lxml import etree
from pyproj import Transformer

T = Transformer.from_crs("EPSG:6697", "EPSG:4326", always_xy=True)
CITYGML_DIR = "citygml"

PILLARS = [(135.762, 34.986), (135.766, 34.985), (135.77, 34.984), (135.773, 34.9835)]
FIRE_RECT = (135.762, 34.988, 135.772, 34.995)  # minLon,minLat,maxLon,maxLat

def local(tag):
    return tag.rsplit("}", 1)[-1] if "}" in tag else tag.split(":")[-1]

def text_of(el, name):
    for c in el.iter():
        if local(c.tag) == name and c.text and c.text.strip():
            return c.text.strip()
    return ""

def footprint_centroid_area(bel):
    """first lod0FootPrint exterior ring -> centroid(x,y in 6697), area m2"""
    for c in bel.iter():
        if local(c.tag) == "lod0FootPrint":
            for ring in c.iter():
                if local(ring.tag) == "LinearRing":
                    for pl in ring.iter():
                        if local(pl.tag) == "posList" and pl.text:
                            nums = [float(x) for x in pl.text.split()]
                            xs = nums[0::3]
                            ys = nums[1::3]
                            n = len(xs)
                            if n < 3:
                                return None
                            area2 = sum(xs[i] * ys[(i + 1) % n] - xs[(i + 1) % n] * ys[i] for i in range(n))
                            area = abs(area2) / 2
                            cx = sum((xs[i] + xs[(i + 1) % n]) * (xs[i] * ys[(i + 1) % n] - xs[(i + 1) % n] * ys[i]) for i in range(n)) / (6 * (area2 / 2) if area2 else 1)
                            cy = sum((ys[i] + ys[(i + 1) % n]) * (xs[i] * ys[(i + 1) % n] - xs[(i + 1) % n] * ys[i]) for i in range(n)) / (6 * (area2 / 2) if area2 else 1)
                            if not math.isfinite(cx) or not math.isfinite(cy):
                                cx, cy = sum(xs) / n, sum(ys) / n
                            return cx, cy, area
    return None

def flood_depth(bel):
    for c in bel.iter():
        if local(c.tag) == "RiverFloodingRiskAttribute":
            d = text_of(c, "depth")
            try:
                return float(d)
            except Exception:
                return -1.0
    return 0.0

def parse_file(path):
    stats = {"count": 0, "wooden": 0, "old": 0, "flood": 0,
             "maxH": 0.0, "sumH": 0.0, "footArea": 0.0, "structures": {}}
    wooden_pts = []
    fire_count = 0
    ctx = etree.iterparse(path, events=("end",), huge_tree=True)
    for _, el in ctx:
        if local(el.tag) != "Building":
            continue
        stats["count"] += 1
        try:
            h = float(text_of(el, "measuredHeight") or 0)
        except Exception:
            h = 0.0
        y = text_of(el, "yearOfConstruction")[:4]
        st = text_of(el, "buildingStructureType")
        stats["structures"][st] = stats["structures"].get(st, 0) + 1
        stats["maxH"] = max(stats["maxH"], h)
        stats["sumH"] += h
        is_wood = ("木" in st) or ("wood" in st.lower())
        try:
            yi = int(y) if y.isdigit() else 9999
        except Exception:
            yi = 9999
        is_old = yi <= 1980
        if is_wood:
            stats["wooden"] += 1
        if is_old:
            stats["old"] += 1
        fp = footprint_centroid_area(el)
        lon = lat = None
        if fp:
            cx, cy, area = fp
            stats["footArea"] += area
            lon, lat = T.transform(cx, cy)
        fd = flood_depth(el)
        if fd and fd > 0:
            stats["flood"] += 1
        if (is_wood or is_old) and lon is not None:
            wooden_pts.append({"lon": round(lon, 6), "lat": round(lat, 6),
                               "h": round(h, 1), "w": 1 if is_wood else 0})
        if lon is not None and FIRE_RECT[0] <= lon <= FIRE_RECT[2] and FIRE_RECT[1] <= lat <= FIRE_RECT[3]:
            fire_count += 1
        el.clear()
        while el.getprevious() is not None:
            del el.getparent()[0]
    del ctx
    stats["fire_rect_count"] = fire_count
    return stats, wooden_pts

def main():
    codes = sys.argv[1:] or sorted(f.replace(".gml", "") for f in os.listdir(CITYGML_DIR) if f.endswith(".gml"))
    all_stats, all_wood = {}, []
    for code in codes:
        p = os.path.join(CITYGML_DIR, code + ".gml")
        if not os.path.isfile(p):
            print(code, "missing, skip")
            continue
        print(code, "parsing...", flush=True)
        st, wp = parse_file(p)
        st["avgH"] = round(st["sumH"] / st["count"], 1) if st["count"] else 0
        print(code, json.dumps({k: (v if k != "structures" else "...") for k, v in st.items()}, ensure_ascii=False))
        print(code, "structures:", json.dumps(st["structures"], ensure_ascii=False)[:400])
        all_stats[code] = st
        all_wood.extend(wp)
    # pillar clearance: max height within 40m of each pillar
    # (approx: 1deg lat ~111km; use rough box 0.0004deg)
    for i, (plon, plat) in enumerate(PILLARS):
        mh = 0.0
        for w in all_wood:
            pass
        print(f"pillar{i}: ({plon},{plat})")
    json.dump({"meshes": all_stats, "counts": {k: sum(s[k] for s in all_stats.values()) for k in ("count", "wooden", "old", "flood", "fire_rect_count")}},
              open("stats.json", "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    json.dump(all_wood, open("wooden.json", "w", encoding="utf-8"), ensure_ascii=False)
    import os as _o
    print("stats.json + wooden.json written;",
          "wooden pts:", len(all_wood),
          "wooden.json MB:", round(_o.path.getsize("wooden.json") / 1048576, 2))

main()

from lxml import etree

def local(tag):
    return tag.rsplit("}", 1)[-1] if "}" in tag else tag.split(":")[-1]

path = "citygml/52353671.gml"
ctx = etree.iterparse(path, events=("end",), huge_tree=True)
n = 0
for _, el in ctx:
    if local(el.tag) != "Building":
        continue
    n += 1
    if n == 1:
        print("--- first Building subtree (depth<=6, foot/lod related) ---")
        def walk(e, d):
            if d > 7:
                return
            t = local(e.tag)
            if any(k in t.lower() for k in ("lod", "foot", "polygon", "ring", "pos", "surface", "exterior", "solid", "composite", "geometry", "envelope", "bound")):
                txt = (e.text or "").strip()
                print("  " * d + t + (f" [{len(txt)} chars]" if len(txt) > 60 else (f" = {txt[:60]}" if txt else "")) + (f" attrs={dict(e.attrib)}" if e.attrib else ""))
            for c in e:
                walk(c, d + 1)
        walk(el, 0)
        # also print structure-related raw values
        print("--- structure/year/usage raw ---")
        for c in el.iter():
            t = local(c.tag)
            if t in ("buildingStructureType", "yearOfConstruction", "usage", "measuredHeight", "storeysAboveGround"):
                print(t, "=", (c.text or "").strip()[:80])
        el.clear()
        break
    el.clear()

