from lxml import etree
from collections import Counter
import re

def local(tag):
    return tag.rsplit("}", 1)[-1] if "}" in tag else tag.split(":")[-1]

for path in ("citygml/52353672.gml", "citygml/52353671.gml"):
    print("=" * 20, path)
    # tail integrity
    with open(path, "rb") as f:
        f.seek(-200, 2)
        print("tail:", f.read()[-120:])
    ctx = etree.iterparse(path, events=("end",), huge_tree=True)
    heights = []
    rings = 0
    for _, el in ctx:
        if local(el.tag) != "Building":
            continue
        for c in el.iter():
            if local(c.tag) == "measuredHeight" and c.text and c.text.strip():
                try:
                    heights.append(float(c.text.strip()))
                except Exception:
                    pass
                break
        if rings == 0:
            for c in el.iter():
                if local(c.tag) == "lod0RoofEdge":
                    for ring in c.iter():
                        if local(ring.tag) == "LinearRing":
                            for pl in ring.iter():
                                if local(pl.tag) == "posList" and pl.text:
                                    nums = [float(x) for x in pl.text.split()]
                                    print("stride3 count:", len(nums) // 3, "first12:", nums[:12])
                                    rings += 1
                                    break
                            break
                    break
        el.clear()
        while el.getprevious() is not None:
            del el.getparent()[0]
        if len(heights) >= 8 and rings >= 1:
            pass
        if len(heights) >= 2000 and rings >= 1:
            break
    del ctx
    print("heights sample:", heights[:10])
    print("neg count:", sum(1 for h in heights if h < 0), "/", len(heights))
    hc = Counter(round(h, 1) for h in heights)
    print("top heights:", hc.most_common(8))

from lxml import etree

def local(tag):
    return tag.rsplit("}", 1)[-1] if "}" in tag else tag.split(":")[-1]

def text_of(el, name):
    for c in el.iter():
        if local(c.tag) == name and c.text and c.text.strip():
            return c.text.strip()
    return ""

path = "citygml/52353672.gml"
ctx = etree.iterparse(path, events=("end",), huge_tree=True)
n = 0
neg = []
for _, el in ctx:
    if local(el.tag) != "Building":
        continue
    n += 1
    raw = text_of(el, "measuredHeight")
    try:
        h = float(raw or 0)
    except Exception:
        h = 0.0
    if n <= 5:
        print(n, repr(raw), "->", h)
    if h < 0:
        neg.append((n, raw))
    el.clear()
    while el.getprevious() is not None:
        del el.getparent()[0]
    if n >= 1385:
        break
print("total:", n, "negatives:", neg[:10])

