// 放水ライン: アクティブコース中間点から火点へ（コース切替で更新）
const waterLine = viewer.entities.add({
  polyline: {
    positions: new Cesium.CallbackProperty(() => {
      const c = activeCourse();
      const mid = c.route[Math.floor(c.route.length / 2)];
