preload = """
// ---- 13. 初回一括プリロード ----
// デモ地点を順に訪れてタイルを先読みし、2回目以降のカクつきを消す。
const PRELOAD_VIEWS: Array<{ lon: number; lat: number; h: number; label: string }> = [
  { lon: 135.7585, lat: 34.9875, h: 1400, label: "京都駅上空" },
  { lon: 135.758, lat: 34.987, h: 500, label: "ファミリーSTART" },
